  [`/projects/${PROJECT}/vulnerabilities`]: ['Findings', 'Found in', 'lodash', '4.17.21'],
  [`/projects/${PROJECT}/environments`]: ['Payment Service', 'Production', '4.2.0', 'Manage', 'New environment'],
  [`/projects/${PROJECT}/pipelines`]: ['Security pipeline', '#1', 'Passed', 'Run pipeline', 'Payment Service'],
  [`/projects/${PROJECT}/pipelines/pipe1`]: ['Security pipeline', 'source', 'scan', 'checkout', 'code', 'Stages'],
  [`/projects/${PROJECT}/jobs/job1`]: ['checkout', 'Passed', 'cloning acme-org/payment-api over ssh', 'Result', 'Retry'],
  [`/projects/${PROJECT}/runners`]: ['wsl-runner', 'online', 'New pool', 'Runners available', 'Default pool', 'acme-runner-0'],
  '/runners': ['wsl-runner', 'Register runner', 'devbox', 'Pools at this level', 'acme-runner-0', '(managed)'],
